with flattened_attrs as (select id, plan, effective_from, tier_limits, transform(tier_prices, (p, i) -> round(p * tier_limits[i], 2)) as tier_revenue_caps, zip_with(tier_prices, discounts, (p, d) -> round(p * (1 - d), 2)) as net_prices from price_tiers where month(effective_from) in (7, 11, 12)) select date_trunc('week', effective_from) as week_start, sort_array(collect_set(plan)) as plan_list, sort_array(collect_set(plan)) as plan_list_2, count_if(plan = 'enterprise') as enterprise_events from flattened_attrs group by date_trunc('week', effective_from) order by enterprise_events desc;
